function renderActionOptions(){
  document.querySelector('#actionOptions').innerHTML=actionGroups.map(group=>`<section class="option-group"><h3>${group.title}</h3><div class="checkbox-grid">${group.options.map(([id,label])=>`<label class="checkbox-option"><input type="checkbox" value="${id}" ${savedSelection.has(id)?'checked':''}><span>[${id}] ${label}</span></label>`).join('')}</div></section>`).join('');
  updateCount();
}
function updateCount(){document.querySelector('#selectedCount').textContent=document.querySelectorAll('#actionOptions input:checked').length}
function setContinuationPromptError(visible){const input=document.querySelector('#continuationPromptInput');input.classList.toggle('input-error',visible);input.setAttribute('aria-invalid',String(visible));document.querySelector('#continuationPromptError').hidden=!visible}
function setMode(mode){
  document.querySelectorAll('.mode-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.mode===mode));
  document.querySelector('#generalMode').hidden=mode!=='general';
  document.querySelector('#customMode').hidden=mode!=='custom';
  if(mode!=='custom')setContinuationPromptError(false);
  document.querySelector('#confirmModal').textContent=mode==='custom'?'确认':'确定';
}
function openModal(){renderActionOptions();document.querySelector('#firstPromptInput').value=savedFirstPrompt;document.querySelector('#continuationPromptInput').value=savedContinuationPrompt;setContinuationPromptError(false);setMode(savedMode);document.querySelector('#actionModal').hidden=false;document.body.classList.add('modal-open')}
function closeModal(){document.querySelector('#actionModal').hidden=true;setContinuationPromptError(false);document.body.classList.remove('modal-open')}
function renderQuestionList(){document.querySelector('#questionList').innerHTML=questionItems.map((value,index)=>`<div class="question-row"><span class="question-index">${index+1}</span><input class="question-input" aria-label="问题 ${index+1}" value="${value.replace(/"/g,'&quot;')}" placeholder="请输入问题内容"><button class="remove-question" aria-label="删除问题" ${questionItems.length<=1?'disabled':''}>×</button></div>`).join('')}
function openQuestionModal(){document.querySelector('#questionTitleInput').value=questionTitle;renderQuestionList();document.querySelector('#questionModal').hidden=false;document.body.classList.add('modal-open')}
function closeQuestionModal(){document.querySelector('#questionModal').hidden=true;document.body.classList.remove('modal-open')}
function updateActionSummary(){
  const summary=document.querySelector('#actionSummary');
  if(!actionEnabled){summary.textContent='动作设计已关闭';summary.classList.add('summary-disabled');return}
  summary.classList.remove('summary-disabled');
  const configuredPromptCount=[savedFirstPrompt,savedContinuationPrompt].filter(prompt=>prompt.trim()).length;
  summary.textContent=savedMode==='general'?`通用模式 · 已选择 ${savedSelection.size} 项`:`自定义模式 · 已配置 ${configuredPromptCount} / 2 个 Prompt`;
}
