document.querySelector('#confirmModal').addEventListener('click',()=>{
  const mode=document.querySelector('.mode-tab.active').dataset.mode;
  if(mode==='custom'){
    const firstPrompt=document.querySelector('#firstPromptInput').value;
    const continuationPrompt=document.querySelector('#continuationPromptInput').value;
    if(firstPrompt.trim()&&!continuationPrompt.trim()){
      setContinuationPromptError(true);
      document.querySelector('#continuationPromptInput').focus();
      return;
    }
    savedFirstPrompt=firstPrompt;
    savedContinuationPrompt=continuationPrompt;
  }else{
    savedSelection=new Set([...document.querySelectorAll('#actionOptions input:checked')].map(input=>input.value));
  }
  savedMode=mode;
  updateActionSummary();
  closeModal();
});
