const escapeHtml=value=>String(value).replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
function renderFallbackReplies(){const list=document.querySelector('#fallbackList');list.innerHTML=riskDraft.fallbacks.map((reply,index)=>`<div class="fallback-row"><span>${index+1}</span><input class="fallback-input" value="${escapeHtml(reply)}" placeholder="请输入兜底回复"><button class="remove-risk-item" data-fallback-index="${index}" aria-label="删除兜底回复">×</button></div>`).join('');document.querySelector('#fallbackCount').textContent=`${riskDraft.fallbacks.length} / 10`;document.querySelector('#addFallback').disabled=riskDraft.fallbacks.length>=10}
function renderRiskCategories(type){const target=document.querySelector(type==='input'?'#inputRiskCategories':'#outputRiskCategories');target.innerHTML=riskDraft[type].map((category,index)=>`<article class="risk-category"><div class="risk-category-head"><input class="risk-category-name" data-risk-type="${type}" data-risk-index="${index}" value="${escapeHtml(category.name)}" placeholder="分类${index+1}"><button class="remove-risk-item" data-remove-category="${type}" data-risk-index="${index}" aria-label="删除分类">×</button></div><textarea class="risk-words" data-risk-type="${type}" data-risk-index="${index}" placeholder="请输入需要风控的词，例如：词语A，词语B；词语C">${escapeHtml(category.words)}</textarea><p>词与词之间可使用任意标点或空格分隔</p></article>`).join('')}
function syncRiskDraft(){riskDraft.fallbacks=[...document.querySelectorAll('.fallback-input')].map(input=>input.value);['input','output'].forEach(type=>{riskDraft[type]=[...document.querySelectorAll(`.risk-category-name[data-risk-type="${type}"]`)].map((input,index)=>({name:input.value,words:document.querySelector(`.risk-words[data-risk-type="${type}"][data-risk-index="${index}"]`).value}))})}
function openRiskModal(){riskDraft={fallbacks:[...fallbackReplies],input:riskCategories.input.map(item=>({...item})),output:riskCategories.output.map(item=>({...item}))};renderFallbackReplies();renderRiskCategories('input');renderRiskCategories('output');document.querySelector('#riskModal').hidden=false;document.body.classList.add('modal-open')}
function closeRiskModal(){document.querySelector('#riskModal').hidden=true;document.body.classList.remove('modal-open');riskDraft=null}
function updateRiskSummary(){const summary=document.querySelector('#riskSummary');summary.classList.toggle('summary-disabled',!riskEnabled);summary.textContent=riskEnabled?`${fallbackReplies.length} 条兜底 · 输入 ${riskCategories.input.length} 类 · 输出 ${riskCategories.output.length} 类`:'定制风控已关闭'}
document.querySelector('#openRiskDesign').addEventListener('click',openRiskModal);
document.querySelector('#closeRiskModal').addEventListener('click',closeRiskModal);
document.querySelector('#cancelRiskModal').addEventListener('click',closeRiskModal);
document.querySelector('#riskModal').addEventListener('click',event=>{if(event.target.id==='riskModal')closeRiskModal()});
document.querySelector('#riskEnabled').addEventListener('change',event=>{riskEnabled=event.target.checked;updateRiskSummary()});
document.querySelector('#addFallback').addEventListener('click',()=>{syncRiskDraft();if(riskDraft.fallbacks.length<10){riskDraft.fallbacks.push('');renderFallbackReplies();document.querySelector('.fallback-row:last-child .fallback-input').focus()}});
document.querySelector('#fallbackList').addEventListener('click',event=>{if(!event.target.dataset.fallbackIndex)return;syncRiskDraft();riskDraft.fallbacks.splice(Number(event.target.dataset.fallbackIndex),1);if(!riskDraft.fallbacks.length)riskDraft.fallbacks.push('');renderFallbackReplies()});
document.querySelectorAll('.add-risk-category').forEach(button=>button.addEventListener('click',()=>{syncRiskDraft();const type=button.dataset.riskType;riskDraft[type].push({name:'',words:''});renderRiskCategories(type);document.querySelector(`#${type}RiskCategories .risk-category:last-child .risk-category-name`).focus()}));
document.querySelectorAll('.risk-category-list').forEach(list=>list.addEventListener('click',event=>{const type=event.target.dataset.removeCategory;if(!type)return;syncRiskDraft();riskDraft[type].splice(Number(event.target.dataset.riskIndex),1);if(!riskDraft[type].length)riskDraft[type].push({name:'',words:''});renderRiskCategories(type)}));
document.querySelector('#confirmRiskModal').addEventListener('click',()=>{syncRiskDraft();fallbackReplies=riskDraft.fallbacks.map(item=>item.trim()).filter(Boolean).slice(0,10);if(!fallbackReplies.length)fallbackReplies=['不好意思，这个话题我不方便讨论，我们聊点别的吧'];['input','output'].forEach(type=>{riskCategories[type]=riskDraft[type].map((item,index)=>({name:item.name.trim()||`分类${index+1}`,words:item.words.trim()}))});updateRiskSummary();closeRiskModal()});
