function renderFaqGroups(){faqDraft.forEach(g=>g.queries=g.queries.map(q=>typeof q==='string'?{text:q,mode:'fuzzy',exactType:'contains'}:q));document.querySelector('#faqGroups').innerHTML=faqDraft.map((g,i)=>`<article class="faq-group"><div class="faq-group-head"><strong>问答组 ${i+1}</strong><button class="remove-faq-group" data-index="${i}" aria-label="删除问答组">×</button></div><div class="faq-label">Query <span>可添加多个 Query，共享同一个 Answer</span></div><div class="faq-queries">${g.queries.map((q,qi)=>`<div class="faq-query-row"><input class="faq-query-input" data-group="${i}" data-query="${qi}" value="${escapeHtml(q.text)}" placeholder="请输入 Query"><select class="faq-query-mode" data-group="${i}" data-query="${qi}"><option value="fuzzy" ${q.mode==='fuzzy'?'selected':''}>模糊匹配</option><option value="exact" ${q.mode==='exact'?'selected':''}>精确匹配</option></select><select class="faq-query-exact" data-group="${i}" data-query="${qi}" ${q.mode==='exact'?'':'hidden'}><option value="contains" ${q.exactType==='contains'?'selected':''}>包含关系</option><option value="equals" ${q.exactType==='equals'?'selected':''}>完全匹配</option></select><button class="remove-faq-query" data-group="${i}" data-query="${qi}" aria-label="删除 Query">×</button></div>`).join('')}</div><button class="add-faq-query text-action" data-group="${i}">＋ 添加 Query</button><div class="faq-label answer-label">Answer</div><textarea class="faq-answer-input" data-group="${i}" placeholder="请输入固定回复内容">${escapeHtml(g.answer)}</textarea></article>`).join('')}
function openFaqModal(){faqDraft=faqGroups.map(g=>({queries:g.queries.map(q=>typeof q==='string'?{text:q,mode:'fuzzy',exactType:'contains'}:{...q}),answer:g.answer}));renderFaqGroups();document.querySelector('#faqModal').hidden=false;document.body.classList.add('modal-open')}
function closeFaqModal(){document.querySelector('#faqModal').hidden=true;document.body.classList.remove('modal-open');faqDraft=null}
function updateFaqSummary(){const e=document.querySelector('#faqSummary');e.classList.toggle('summary-disabled',!faqEnabled);e.textContent=faqEnabled?`${faqGroups.length} 组问答 · Query 独立匹配`:'FAQ 已关闭'}
function syncFaqDraft(){faqDraft.forEach((g,i)=>{g.queries=[...document.querySelectorAll(`.faq-query-input[data-group="${i}"]`)].map((x,qi)=>({text:x.value,mode:document.querySelector(`.faq-query-mode[data-group="${i}"][data-query="${qi}"]`).value,exactType:document.querySelector(`.faq-query-exact[data-group="${i}"][data-query="${qi}"]`).value,trim(){this.text=this.text.trim();return this}}));g.answer=document.querySelector(`.faq-answer-input[data-group="${i}"]`).value})}
document.querySelector('#openFaqDesign').addEventListener('click',openFaqModal);document.querySelector('#closeFaqModal').addEventListener('click',closeFaqModal);document.querySelector('#cancelFaqModal').addEventListener('click',closeFaqModal);document.querySelector('#faqModal').addEventListener('click',e=>{if(e.target.id==='faqModal')closeFaqModal()});document.querySelectorAll('input[name="faqMatchMode"]').forEach(r=>r.addEventListener('change',()=>{faqMatchMode=r.value;document.querySelector('#faqExactMode').hidden=faqMatchMode!=='exact'}));document.querySelector('#addFaqGroup').addEventListener('click',()=>{syncFaqDraft();faqDraft.push({queries:[''],answer:''});renderFaqGroups()});document.querySelector('#faqGroups').addEventListener('click',e=>{if(e.target.classList.contains('add-faq-query')){syncFaqDraft();faqDraft[Number(e.target.dataset.group)].queries.push('');renderFaqGroups()}if(e.target.classList.contains('remove-faq-query')){syncFaqDraft();faqDraft[Number(e.target.dataset.group)].queries.splice(Number(e.target.dataset.query),1);if(!faqDraft[Number(e.target.dataset.group)].queries.length)faqDraft[Number(e.target.dataset.group)].queries.push('');renderFaqGroups()}if(e.target.classList.contains('remove-faq-group')){syncFaqDraft();faqDraft.splice(Number(e.target.dataset.index),1);if(!faqDraft.length)faqDraft.push({queries:[''],answer:''});renderFaqGroups()}});document.querySelector('#confirmFaqModal').addEventListener('click',()=>{syncFaqDraft();faqGroups=faqDraft.map(g=>({queries:g.queries.map(q=>q.trim()).filter(Boolean),answer:g.answer.trim()})).filter(g=>g.queries.length||g.answer);if(!faqGroups.length)faqGroups=[{queries:[''],answer:''}];faqExactType=document.querySelector('input[name="faqExactType"]:checked')?.value||'contains';updateFaqSummary();closeFaqModal()});document.querySelector('#faqEnabled').addEventListener('change',e=>{faqEnabled=e.target.checked;updateFaqSummary()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#faqModal').hidden)closeFaqModal()});
document.querySelectorAll('input[name="faqExactType"]').forEach(r=>r.addEventListener('change',()=>{}));document.querySelector('#faqGroups').addEventListener('change',e=>{if(!e.target.classList.contains('faq-query-mode'))return;const exact=document.querySelector(`.faq-query-exact[data-group="${e.target.dataset.group}"][data-query="${e.target.dataset.query}"]`);exact.hidden=e.target.value!=='exact'});
function normalizeFaqQueries(){if(!faqDraft)return;faqDraft.forEach(g=>{g.queries=g.queries.map(q=>{if(typeof q==='string')return {text:q,mode:'fuzzy',exactType:'contains',trim(){this.text=this.text.trim();return this}};if(!q.trim)q.trim=function(){this.text=this.text.trim();return this};return q})})}document.querySelector('#faqGroups').addEventListener('click',()=>setTimeout(normalizeFaqQueries,0));
function renderInterventionRules(){document.querySelector('#interventionRules').innerHTML=interventionDraft.map((rule,index)=>`<div class="intervention-row"><textarea class="intervention-source" data-index="${index}" placeholder="请输入要替换的词或句子">${escapeHtml(rule.source)}</textarea><textarea class="intervention-replacement" data-index="${index}" placeholder="请输入替换后的内容">${escapeHtml(rule.replacement)}</textarea><select class="intervention-match" data-index="${index}"><option value="equals" ${rule.match==='equals'?'selected':''}>完全匹配</option><option value="contains" ${rule.match==='contains'?'selected':''}>包含关系</option><option value="regex" ${rule.match==='regex'?'selected':''}>正则匹配</option></select><button class="remove-intervention" data-index="${index}" aria-label="删除规则">×</button></div>`).join('')}
function syncInterventionDraft(){interventionDraft=[...document.querySelectorAll('.intervention-source')].map((source,index)=>({source:source.value,replacement:document.querySelector(`.intervention-replacement[data-index="${index}"]`).value,match:document.querySelector(`.intervention-match[data-index="${index}"]`).value}))}
function openInterventionModal(){interventionDraft=interventionRules.map(rule=>({...rule}));renderInterventionRules();document.querySelector('#interventionModal').hidden=false;document.body.classList.add('modal-open')}
