function updateInterventionSummary(){const e=document.querySelector('#interventionSummary');e.classList.toggle('summary-disabled',!interventionEnabled);e.textContent=interventionEnabled?`${interventionRules.length} 条替换规则`:'输出内容干预已关闭'}
document.querySelector('#openInterventionDesign').addEventListener('click',openInterventionModal);document.querySelector('#closeInterventionModal').addEventListener('click',closeInterventionModal);document.querySelector('#cancelInterventionModal').addEventListener('click',closeInterventionModal);document.querySelector('#interventionModal').addEventListener('click',e=>{if(e.target.id==='interventionModal')closeInterventionModal()});document.querySelector('#addInterventionRule').addEventListener('click',()=>{syncInterventionDraft();interventionDraft.push({source:'',replacement:'',match:'contains'});renderInterventionRules();document.querySelector('.intervention-row:last-child .intervention-source').focus()});document.querySelector('#interventionRules').addEventListener('click',e=>{if(!e.target.classList.contains('remove-intervention'))return;syncInterventionDraft();interventionDraft.splice(Number(e.target.dataset.index),1);if(!interventionDraft.length)interventionDraft.push({source:'',replacement:'',match:'contains'});renderInterventionRules()});document.querySelector('#confirmInterventionModal').addEventListener('click',()=>{syncInterventionDraft();interventionRules=interventionDraft.map(rule=>({source:rule.source.trim(),replacement:rule.replacement,match:rule.match})).filter(rule=>rule.source||rule.replacement);if(!interventionRules.length)interventionRules=[{source:'',replacement:'',match:'contains'}];updateInterventionSummary();closeInterventionModal()});document.querySelector('#interventionEnabled').addEventListener('change',e=>{interventionEnabled=e.target.checked;updateInterventionSummary()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#interventionModal').hidden)closeInterventionModal()});
let leadEnabled=false,leadConfig={triggerRounds:3,maxTimes:3,rejectLimit:3};function updateLeadSummary(){const e=document.querySelector('#leadSummary');e.classList.toggle('summary-disabled',!leadEnabled);e.textContent=leadEnabled?`每 ${leadConfig.triggerRounds} 轮 · 最多 ${leadConfig.maxTimes} 次 · 拒绝 ${leadConfig.rejectLimit} 次禁用`:'对话留资已关闭'}function openLeadModal(){document.querySelector('#leadTriggerRounds').value=leadConfig.triggerRounds;document.querySelector('#leadMaxTimes').value=leadConfig.maxTimes;document.querySelector('#leadRejectLimit').value=leadConfig.rejectLimit;document.querySelector('#leadModal').hidden=false;document.body.classList.add('modal-open')}function closeLeadModal(){document.querySelector('#leadModal').hidden=true;document.body.classList.remove('modal-open')}document.querySelector('#openLeadDesign').addEventListener('click',openLeadModal);document.querySelector('#closeLeadModal').addEventListener('click',closeLeadModal);document.querySelector('#cancelLeadModal').addEventListener('click',closeLeadModal);document.querySelector('#leadModal').addEventListener('click',e=>{if(e.target.id==='leadModal')closeLeadModal()});document.querySelector('#leadEnabled').addEventListener('change',e=>{leadEnabled=e.target.checked;updateLeadSummary()});document.querySelector('#confirmLeadModal').addEventListener('click',()=>{const value=id=>Math.max(0,Math.min(100,Number(document.querySelector(id).value)||0));leadConfig={triggerRounds:value('#leadTriggerRounds'),maxTimes:value('#leadMaxTimes'),rejectLimit:value('#leadRejectLimit')};updateLeadSummary();closeLeadModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#leadModal').hidden)closeLeadModal()});
let memoryEnabled=false;function updateMemorySummary(){const e=document.querySelector('#memorySummary');e.classList.toggle('summary-disabled',!memoryEnabled);e.textContent=memoryEnabled?'已启用 · 保留 24 小时':'24小时记忆已关闭'}document.querySelector('#memoryEnabled').addEventListener('change',e=>{memoryEnabled=e.target.checked;updateMemorySummary()});
let interruptEnabled=false,interruptLevels={redundancy:0,correction:0,emotion:0};function updateInterruptSummary(){const e=document.querySelector('#interruptSummary');e.classList.toggle('summary-disabled',!interruptEnabled);e.textContent=interruptEnabled?`冗余 ${interruptLevels.redundancy} · 纠偏 ${interruptLevels.correction} · 情绪 ${interruptLevels.emotion}`:'数字人打断用户已关闭'}function openInterruptModal(){document.querySelector('#redundancyInterrupt').value=interruptLevels.redundancy;document.querySelector('#correctionInterrupt').value=interruptLevels.correction;document.querySelector('#emotionInterrupt').value=interruptLevels.emotion;document.querySelector('#interruptModal').hidden=false;document.body.classList.add('modal-open')}function closeInterruptModal(){document.querySelector('#interruptModal').hidden=true;document.body.classList.remove('modal-open')}function normalizeInterruptLevel(id){const input=document.querySelector(id);const value=Math.max(0,Math.min(4,Math.round(Number(input.value)||0)));input.value=value;return value}document.querySelector('#openInterruptDesign').addEventListener('click',openInterruptModal);document.querySelector('#closeInterruptModal').addEventListener('click',closeInterruptModal);document.querySelector('#cancelInterruptModal').addEventListener('click',closeInterruptModal);document.querySelector('#interruptModal').addEventListener('click',e=>{if(e.target.id==='interruptModal')closeInterruptModal()});document.querySelector('#interruptEnabled').addEventListener('change',e=>{interruptEnabled=e.target.checked;updateInterruptSummary()});document.querySelector('#confirmInterruptModal').addEventListener('click',()=>{interruptLevels={redundancy:normalizeInterruptLevel('#redundancyInterrupt'),correction:normalizeInterruptLevel('#correctionInterrupt'),emotion:normalizeInterruptLevel('#emotionInterrupt')};updateInterruptSummary();closeInterruptModal()});document.querySelectorAll('#interruptModal input[type="number"]').forEach(input=>input.addEventListener('blur',()=>normalizeInterruptLevel(`#${input.id}`)));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#interruptModal').hidden)closeInterruptModal()});
let templateEnabled=false,templateRules=[{operatorName:'',templateId:'',modelName:'',lang:''}],templateDraft=null;
function renderTemplateRules(){document.querySelector('#templateRules').innerHTML=templateDraft.map((rule,index)=>`<section class="template-rule"><div class="template-rule-head"><strong>配置 ${index+1}</strong><button class="remove-template-rule" data-index="${index}" aria-label="删除配置">×</button></div><div class="template-fields"><label><span>算子名称</span><input class="template-operator" data-index="${index}" value="${escapeHtml(rule.operatorName)}" placeholder="请输入算子名称"></label><label><span>模板 ID</span><input class="template-id" data-index="${index}" value="${escapeHtml(rule.templateId)}" placeholder="请输入模板 ID"></label><label><span>模型名称</span><input class="template-model" data-index="${index}" value="${escapeHtml(rule.modelName)}" placeholder="请输入模型名称"></label><label><span>lang</span><input class="template-lang" data-index="${index}" value="${escapeHtml(rule.lang)}" placeholder="例如 zh-CN"></label></div></section>`).join('')}
function syncTemplateDraft(){templateDraft=[...document.querySelectorAll('.template-rule')].map((_,index)=>({operatorName:document.querySelector(`.template-operator[data-index="${index}"]`).value,templateId:document.querySelector(`.template-id[data-index="${index}"]`).value,modelName:document.querySelector(`.template-model[data-index="${index}"]`).value,lang:document.querySelector(`.template-lang[data-index="${index}"]`).value}))}
function openTemplateModal(){templateDraft=templateRules.map(rule=>({...rule}));renderTemplateRules();document.querySelector('#templateModal').hidden=false;document.body.classList.add('modal-open')}
function closeTemplateModal(){document.querySelector('#templateModal').hidden=true;document.body.classList.remove('modal-open');templateDraft=null}
function updateTemplateSummary(){const e=document.querySelector('#templateSummary');e.classList.toggle('summary-disabled',!templateEnabled);const count=templateRules.filter(rule=>Object.values(rule).some(Boolean)).length;e.textContent=templateEnabled?`已启用 · ${count} 条配置`:'模板及算子干预已关闭'}
document.querySelector('#openTemplateDesign').addEventListener('click',openTemplateModal);document.querySelector('#closeTemplateModal').addEventListener('click',closeTemplateModal);document.querySelector('#cancelTemplateModal').addEventListener('click',closeTemplateModal);document.querySelector('#templateModal').addEventListener('click',e=>{if(e.target.id==='templateModal')closeTemplateModal()});document.querySelector('#templateEnabled').addEventListener('change',e=>{templateEnabled=e.target.checked;updateTemplateSummary()});document.querySelector('#addTemplateRule').addEventListener('click',()=>{syncTemplateDraft();templateDraft.push({operatorName:'',templateId:'',modelName:'',lang:''});renderTemplateRules();document.querySelector('.template-rule:last-child input').focus()});document.querySelector('#templateRules').addEventListener('click',e=>{if(!e.target.classList.contains('remove-template-rule'))return;syncTemplateDraft();templateDraft.splice(Number(e.target.dataset.index),1);if(!templateDraft.length)templateDraft.push({operatorName:'',templateId:'',modelName:'',lang:''});renderTemplateRules()});document.querySelector('#confirmTemplateModal').addEventListener('click',()=>{syncTemplateDraft();templateRules=templateDraft.map(rule=>Object.fromEntries(Object.entries(rule).map(([key,value])=>[key,value.trim()]))).filter(rule=>Object.values(rule).some(Boolean));if(!templateRules.length)templateRules=[{operatorName:'',templateId:'',modelName:'',lang:''}];updateTemplateSummary();closeTemplateModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#templateModal').hidden)closeTemplateModal()});
let retrievalFillerEnabled=true,retrievalFillerConfig={probability:100,parallel:false,delayEnabled:false,delay:0,rounds:3};function updateRetrievalFillerSummary(){const e=document.querySelector('#retrievalFillerSummary');e.classList.toggle('summary-disabled',!retrievalFillerEnabled);e.textContent=retrievalFillerEnabled?`已启用 · 回复概率 ${retrievalFillerConfig.probability}% · 历史 ${retrievalFillerConfig.rounds} 轮`:'检索垫句已关闭'}function openRetrievalFillerModal(){document.querySelector('#retrievalFillerProbability').value=retrievalFillerConfig.probability;document.querySelector('#retrievalFillerParallel').checked=retrievalFillerConfig.parallel;document.querySelector('#retrievalFillerDelayEnabled').checked=retrievalFillerConfig.delayEnabled;document.querySelector('#retrievalFillerDelay').value=retrievalFillerConfig.delay;document.querySelector('#retrievalFillerRounds').value=retrievalFillerConfig.rounds;document.querySelector('#retrievalFillerModal').hidden=false;document.body.classList.add('modal-open')}function closeRetrievalFillerModal(){document.querySelector('#retrievalFillerModal').hidden=true;document.body.classList.remove('modal-open')}function clampRetrievalValue(id,min,max,fallback){const input=document.querySelector(id);const value=Math.max(min,Math.min(max,Math.round(Number(input.value)||fallback)));input.value=value;return value}document.querySelector('#openRetrievalFillerDesign').addEventListener('click',openRetrievalFillerModal);document.querySelector('#closeRetrievalFillerModal').addEventListener('click',closeRetrievalFillerModal);document.querySelector('#cancelRetrievalFillerModal').addEventListener('click',closeRetrievalFillerModal);document.querySelector('#retrievalFillerModal').addEventListener('click',e=>{if(e.target.id==='retrievalFillerModal')closeRetrievalFillerModal()});document.querySelector('#retrievalFillerEnabled').addEventListener('change',e=>{retrievalFillerEnabled=e.target.checked;updateRetrievalFillerSummary()});document.querySelector('#confirmRetrievalFillerModal').addEventListener('click',()=>{retrievalFillerConfig={probability:clampRetrievalValue('#retrievalFillerProbability',0,100,100),parallel:document.querySelector('#retrievalFillerParallel').checked,delayEnabled:document.querySelector('#retrievalFillerDelayEnabled').checked,delay:clampRetrievalValue('#retrievalFillerDelay',0,1000,0),rounds:clampRetrievalValue('#retrievalFillerRounds',0,10,3)};updateRetrievalFillerSummary();closeRetrievalFillerModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#retrievalFillerModal').hidden)closeRetrievalFillerModal()});
let actionTagEnabled=false,actionTagRules=[{tag:'',values:['']}],actionTagDraft=null;
function renderActionTagRules(){document.querySelector('#actionTagRules').innerHTML=actionTagDraft.map((rule,ruleIndex)=>`<section class="action-tag-rule"><div class="action-tag-rule-head"><strong>映射 ${ruleIndex+1}</strong><button class="remove-action-tag-rule" data-rule="${ruleIndex}" aria-label="删除动作 tag">×</button></div><label class="action-tag-field"><span>动作 tag</span><input class="action-tag-input" data-rule="${ruleIndex}" value="${escapeHtml(rule.tag)}" placeholder="例如 [act_03]"></label><div class="action-tag-values-head"><span>映射值</span><button class="add-action-tag-value text-action" data-rule="${ruleIndex}">＋ 新增映射值</button></div><div class="action-tag-values">${rule.values.map((value,valueIndex)=>`<div class="action-tag-value-row"><input class="action-tag-value" data-rule="${ruleIndex}" data-value="${valueIndex}" value="${escapeHtml(value)}" placeholder="请输入映射值"><button class="remove-action-tag-value" data-rule="${ruleIndex}" data-value="${valueIndex}" aria-label="删除映射值">×</button></div>`).join('')}</div><p class="action-tag-error" hidden>请同时填写动作 tag 和至少一个映射值</p></section>`).join('')}
function syncActionTagDraft(){actionTagDraft=[...document.querySelectorAll('.action-tag-rule')].map((rule,ruleIndex)=>({tag:rule.querySelector('.action-tag-input').value,values:[...rule.querySelectorAll('.action-tag-value')].map(input=>input.value)}))}
function openActionTagModal(){actionTagDraft=actionTagRules.map(rule=>({tag:rule.tag,values:[...rule.values]}));renderActionTagRules();document.querySelector('#actionTagModal').hidden=false;document.body.classList.add('modal-open')}
function closeActionTagModal(){document.querySelector('#actionTagModal').hidden=true;document.body.classList.remove('modal-open');actionTagDraft=null}
function updateActionTagSummary(){const summary=document.querySelector('#actionTagSummary');summary.classList.toggle('summary-disabled',!actionTagEnabled);const tagCount=actionTagRules.filter(rule=>rule.tag||rule.values.some(Boolean)).length;const valueCount=actionTagRules.reduce((total,rule)=>total+rule.values.filter(Boolean).length,0);summary.textContent=actionTagEnabled?`已启用 · ${tagCount} 个动作 tag · ${valueCount} 个映射值`:'动作tag映射已关闭'}
document.querySelector('#openActionTagDesign').addEventListener('click',openActionTagModal);document.querySelector('#closeActionTagModal').addEventListener('click',closeActionTagModal);document.querySelector('#cancelActionTagModal').addEventListener('click',closeActionTagModal);document.querySelector('#actionTagModal').addEventListener('click',event=>{if(event.target.id==='actionTagModal')closeActionTagModal()});document.querySelector('#actionTagEnabled').addEventListener('change',event=>{actionTagEnabled=event.target.checked;updateActionTagSummary()});document.querySelector('#addActionTagRule').addEventListener('click',()=>{syncActionTagDraft();actionTagDraft.push({tag:'',values:['']});renderActionTagRules();document.querySelector('.action-tag-rule:last-child .action-tag-input').focus()});document.querySelector('#actionTagRules').addEventListener('input',event=>{const rule=event.target.closest('.action-tag-rule');if(!rule)return;rule.querySelectorAll('.input-error').forEach(input=>input.classList.remove('input-error'));rule.querySelector('.action-tag-error').hidden=true});document.querySelector('#actionTagRules').addEventListener('click',event=>{const addValue=event.target.closest('.add-action-tag-value');const removeValue=event.target.closest('.remove-action-tag-value');const removeRule=event.target.closest('.remove-action-tag-rule');if(!addValue&&!removeValue&&!removeRule)return;syncActionTagDraft();if(addValue){const ruleIndex=Number(addValue.dataset.rule);actionTagDraft[ruleIndex].values.push('');renderActionTagRules();const values=document.querySelectorAll(`.action-tag-value[data-rule="${ruleIndex}"]`);values[values.length-1]?.focus();return}if(removeValue){const ruleIndex=Number(removeValue.dataset.rule);actionTagDraft[ruleIndex].values.splice(Number(removeValue.dataset.value),1);if(!actionTagDraft[ruleIndex].values.length)actionTagDraft[ruleIndex].values.push('');renderActionTagRules();return}actionTagDraft.splice(Number(removeRule.dataset.rule),1);if(!actionTagDraft.length)actionTagDraft.push({tag:'',values:['']});renderActionTagRules()});document.querySelector('#confirmActionTagModal').addEventListener('click',()=>{syncActionTagDraft();const normalized=actionTagDraft.map(rule=>({tag:rule.tag.trim(),values:rule.values.map(value=>value.trim()).filter(Boolean)}));let firstInvalid=null;normalized.forEach((rule,index)=>{if((rule.tag&&!rule.values.length)||(!rule.tag&&rule.values.length)){const section=document.querySelectorAll('.action-tag-rule')[index];section.querySelector('.action-tag-input').classList.toggle('input-error',!rule.tag);if(!rule.values.length)section.querySelector('.action-tag-value').classList.add('input-error');section.querySelector('.action-tag-error').hidden=false;if(!firstInvalid)firstInvalid=section}});if(firstInvalid){firstInvalid.scrollIntoView({behavior:'smooth',block:'center'});return}actionTagRules=normalized.filter(rule=>rule.tag&&rule.values.length);if(!actionTagRules.length)actionTagRules=[{tag:'',values:['']}];updateActionTagSummary();closeActionTagModal()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.querySelector('#actionTagModal').hidden)closeActionTagModal()});
